#!/usr/bin/env python3
"""Build only two unchanged read-only observers with the retained engine's actual host compiler ABI."""
import argparse
import os
from pathlib import Path
import subprocess
from contracts import ROOT,PROFILES,require,load,sha,atomic_json
from processes import OwnedProcess
from inspect_rejection_cpp_abi import abi_tokens,host_macros
import restore_rejection_sdk_header as sdk

SOURCES={'sdk':'Tests/Production/RemainingVessels/NativeProbe.cpp','internal':'Tests/Production/ReloadMath/NativeTouchdown.cpp'}
READERS=['Tests/Production/ReloadMath/TouchdownObservation.h','Tests/Production/ReloadMath/InternalObservation.h','Tests/Production/ReloadMath/SurfaceObservation.h']
COMPILED='ccc02c8a34bd1f227624d8778a141e8736ae8111'


def command(kind,profile,output,root=ROOT):
    require(kind in SOURCES and profile in PROFILES,'Exactly one declared read-only observer and retained profile required')
    engine=root/'out/phase6-hosted-native'/profile/'engine'
    return ['/usr/bin/c++','-std=c++17','-fPIC','-shared','-Wl,--no-undefined','-fsanitize=address,undefined','-fno-omit-frame-pointer','-I'+str(root/'Orbitersdk/include'),'-I'+str(root/'Src/Orbiter'),'-I'+str(engine/'native-sdk'),str(root/SOURCES[kind]),'-L'+str(engine),'-Wl,-rpath,'+str(engine),'-lorbiter_production_vessels','-lorbiter_production_boundary','-ldl','-o',str(output/('remaining-vessels-probe.so' if kind=='sdk' else 'native-internal-observer.so'))]


def validate_command(argv,kind,profile,output,root=ROOT):
    require(argv==command(kind,profile,output,root),'Exact source, SDK, sanitizers and real compiler arguments required; no version macro overrides')


def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--profile',choices=PROFILES,required=True);parser.add_argument('--output',type=lambda p:Path(p).resolve(),required=True);a=parser.parse_args()
    require(os.environ.get('GITHUB_ACTIONS')=='true' and os.environ.get('RUNNER_OS')=='Linux' and Path(os.environ['GITHUB_WORKSPACE']).resolve()==ROOT,'Actual standard hosted compiler only; no local builds')
    require(not a.output.exists() and a.output.is_relative_to(ROOT/'out'),'Fresh separate numerical observer component output required');a.output.mkdir(parents=True)
    report=dict(protocol='phase6-actual-matching-compiler-readonly-numerical-observers-v1',status='building-unqualified',source=os.environ['GITHUB_SHA'],profile=a.profile,compiled_engine_source=COMPILED,actual_compiler=str(Path('/usr/bin/c++').resolve()),actual_compiler_sha256=sha(Path('/usr/bin/c++').resolve()),commands=[],new_simulator_processes=0,original_observer_sources_changed=False,compiler_version_or_ABI_macros_overridden=False,original_runtime_files_replaced=False,numerical_observer_equivalence_qualified=False,complete_numerical_reload_gate_qualified=False,phase6_complete=False,hands_on_ready=False)
    def save():atomic_json(a.output/'proof.json',report)
    try:
        build=ROOT/'out/phase6-hosted-native'/a.profile;record=load(build/'build.json');require(record['source_base']==COMPILED and record['instrumentation']=='address,undefined' and record['owning_sources_unchanged'] is True,'Exact original sanitized compiled engine required')
        runtime={ROOT/name:digest for group in ('runtime_files_sha256','candidate_runtime_files_sha256','generated_source_files_sha256') for name,digest in record[group].items()};require(all(sha(p)==d for p,d in runtime.items()),'Every actual original retained runtime/generated byte must remain exact')
        guards={}
        for name in [*SOURCES.values(),*READERS]:
            path=ROOT/name;require(path.read_bytes()==subprocess.check_output(['git','show',COMPILED+':'+name]),'Original read-only observer source may not change');guards[name]=sha(path)
        sdk_report=sdk.restore(a.profile,build/'build.json',a.output/'original-SDK-header-derivation.json');header=build/'engine/native-sdk/OrbiterNativeBuild.h'
        actual_engine=abi_tokens((build/'engine/liborbiter_production_boundary.so').read_bytes());require(len(actual_engine)==1,'One actual retained compiler ABI required')
        macros=host_macros(header,a.output/'actual-host-preprocessor.log');require(macros['actual_cpp_abi']==actual_engine[0],'Actual standard host compiler must match retained engine ABI; no spoofing')
        report.update(actual_engine_CPP_ABI=actual_engine[0],actual_host_preprocessor=macros,original_sources_sha256=guards,original_SDK_header_derivation=sdk_report);save()
        identities=set()
        for kind in ('sdk','internal'):
            argv=command(kind,a.profile,a.output);validate_command(argv,kind,a.profile,a.output);log=a.output/(kind+'-compile.log')
            with log.open('wb') as stream:
                process=OwnedProcess(argv,cwd=ROOT,env={'PATH':'/usr/bin:/bin','LANG':'C.UTF-8','LC_ALL':'C.UTF-8'},stdout=stream,stderr=subprocess.STDOUT)
                try:process.process.wait(timeout=180)
                finally:receipt=process.cancel()
            atomic_json(a.output/(kind+'-process.json'),receipt);owned=[v for v in receipt['owned_process_identities'] if v['pid']==receipt['actual_collector_pid']]
            require(receipt['terminal'] is True and receipt['cancelled'] is False and receipt['actual_returncode']==0 and len(owned)==1 and owned[0]['argv']==argv and owned[0]['start_ticks']>0,'Actual completed distinct compiler process/start/argv receipt required')
            identity=(owned[0]['pid'],owned[0]['start_ticks']);require(identity not in identities,'One compiler process cannot supply both observers');identities.add(identity)
            binary=Path(argv[-1]);body=binary.read_bytes();require(body[:6]==b'\x7fELF\x02\x01','Actual x64 ELF observer output required')
            dynamic=subprocess.check_output(['readelf','-d',str(binary)],text=True);require('Shared library: [libasan.so.' in dynamic and 'Shared library: [libubsan.so.' in dynamic,'Both original unsuppressed instrumentation linkages required')
            symbols=subprocess.check_output(['nm','-D','--defined-only',str(binary)],text=True);require('_ZN7orbiter10production7Session11EndTimeStep' in symbols,'Actual read-only session forwarding hook required')
            (a.output/(kind+'-dynamic.txt')).write_text(dynamic);(a.output/(kind+'-symbols.txt')).write_text(symbols)
            report['commands'].append(dict(kind=kind,actual_argv=argv,actual_pid=owned[0]['pid'],start_ticks=owned[0]['start_ticks'],actual_returncode=0,process_receipt_sha256=sha(a.output/(kind+'-process.json')),log_sha256=sha(log),output=str(binary),output_sha256=sha(binary),dynamic_sha256=sha(a.output/(kind+'-dynamic.txt')),symbols_sha256=sha(a.output/(kind+'-symbols.txt'))));save()
        require(all(sha(p)==d for p,d in runtime.items()) and all(sha(ROOT/name)==digest for name,digest in guards.items()) and sha(header)==sdk_report['header_sha256'],'Original runtime, source and derived SDK must remain unchanged during actual compilation')
        report.update(status='built-two-unchanged-readonly-numerical-observers-only',actual_original_compiler_processes=2,scope='Component compilation only. No simulator, observation capture, equivalence, numerical/class/candidate or acceptance qualification.')
    except BaseException as error:report.update(status='failed-or-incomplete-unqualified',error=str(error));raise
    finally:save()
    print(report['status'])


if __name__=='__main__':main()
